root.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;ev.preventDefault();const a=b.dataset.action;if(state.busy&&a!=='view-photo')return;switch(a){case'accept-invite':run(acceptInvitation);break;case'invite-login':state.inviteToken=null;state.inviteInvalid=false;state.recovery=false;render();break;case'admin-refresh':run(async()=>{await loadAdminHistory();render();});break;case'copy-invite':run(async()=>{if(!state.isAdmin||state.demo||!state.admin.result?.link)return;try{await navigator.clipboard.writeText(state.admin.result.link);toast('Enlace copiado');}catch{document.querySelector('#invite-link')?.select();toast('Selecciona y copia el enlace.');}});break;case'visit-export':state.modal={kind:'visit-export'};renderModal();break;case'cover-photo':state.modal.coverKey=b.dataset.key;refreshMealStrip();break;case'theme':state.theme=applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');render();break;case'demo-preview':if(!state.demo)return;for(const value of photoUrls.values())if(value.url.startsWith('blob:'))URL.revokeObjectURL(value.url);photoUrls.clear();state.data=makeDemoData(today());state.demoLoaded=true;state.period=startFor(today());state.reportWeek=mondayOf(today());state.open=today();state.bodyBefore='';state.bodyAfter='';render();toast('120 días ficticios cargados. No se guardan en Supabase.');break;case'body-angle':state.bodyAngle=b.dataset.angle;render();break;case'body-view':{const row=state.data.body_photos.find(r=>r.id===b.dataset.id),paths=bodyPaths(row);photoViewer.open(paths,Math.max(0,paths.indexOf(row[b.dataset.angle])));break;}case'body-remove':{const angle=b.dataset.angle,path=state.modal.bodyPhotos[angle];if(path)state.modal.removed.push(path);state.modal.bodyPhotos[angle]=null;document.querySelector(`[data-body-preview="${angle}"]`).innerHTML='<span>Sin foto</span>';break;}case'help':state.modal={kind:'help'};renderModal();break;case'tour-start':state.modal=null;state.tourStep=0;state.view='summary';state.period=startFor(today());state.open=today();render();break;case'tour-prev':case'tour-next':state.tourStep=Math.max(0,Math.min(TOUR.length-1,state.tourStep+(a==='tour-next'?1:-1)));state.view=TOUR[state.tourStep].view;if(state.view==='summary')state.open=today();render();document.querySelector(TOUR[state.tourStep].target)?.scrollIntoView({block:'center',behavior:'smooth'});break;case'tour-finish':run(async()=>{await save('profiles',{...profile(),onboarding_completed:true});await refresh();state.tourStep=null;render();});break;case'report-prev':case'report-next':state.reportWeek=addDays(state.reportWeek,a==='report-prev'?-7:7);render();break;case'report-current':state.reportWeek=mondayOf(today());render();break;case'report-metric':state.reportMetric=b.dataset.metric;render();break;case'goal-template':state.modal.goalTemplate=b.dataset.template;renderModal();break;case'goal-choose':state.modal.goalTemplate=null;renderModal();break;case'goal-progress':state.modal={kind:'goal-progress',goal:state.data.goals.find(g=>g.id===b.dataset.id),date:b.dataset.date,removed:[]};renderModal();break;case'view-meal-photo':{const meal=state.data.meals.find(m=>m.id===b.dataset.id);if(meal?.photos?.length)photoViewer.open(meal.photos);break;}case'show-password':{const input=document.querySelector('[name=password]');const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Ocultar contraseña':'Mostrar contraseña';b.setAttribute('aria-pressed',String(show));break;}case'nav':if(b.dataset.view==='admin'&&(!state.isAdmin||state.demo))return;state.view=b.dataset.view;state.menu=false;render();window.scrollTo(0,0);if(state.view==='admin')run(async()=>{await loadAdminHistory();render();});break;case'home':state.view='summary';render();break;case'menu':state.menu=!state.menu;render();break;case'day':state.open=state.open===b.dataset.date?'':b.dataset.date;if(state.open)state.period=startFor(state.open);render();break;case'prev':case'next':state.period=addDays(state.period,a==='prev'?-span():span());state.open='';render();break;case'current':state.period=startFor(today());state.open=today();render();break;case'measurement-select':if(MEASURES.some(m=>m.key===b.dataset.key)){state.measurementMetric=b.dataset.key;render();document.querySelector('.measurement-card.selected')?.focus();}break;case'body':case'measurement':case'meal':case'exercise':case'goal':case'milestone':case'weight':case'appointment':case'profile':openModal(a,b.dataset.id,b.dataset.date,b.dataset.type);break;case'close':disposeMealDrafts(state.modal);state.modal=null;render();break;case'demo':startDemo();break;case'logout':run(async()=>{if(state.demo){for(const v of photoUrls.values())if(v.url.startsWith('blob:'))URL.revokeObjectURL(v.url);}else{const {error}=await db.auth.signOut();if(error)throw error;}resetAdmin();state.view='summary';state.session=null;state.demo=false;state.modal=null;state.tourStep=null;photoUrls.clear();state.data=Object.fromEntries(tables.map(t=>[t,[]]));render();});break;case'refresh':run(async()=>{await refresh();await refreshAdminRole();if(state.view==='admin'&&state.isAdmin)await loadAdminHistory();state.error='';render();toast('Actualizado');});break;case'delete':run(deleteEntry);break;case'remove-photo':{const m=state.modal,key=b.dataset.key;if(key.startsWith('draft:')){const entry=m.newFiles.find(x=>x.key===key);if(entry)URL.revokeObjectURL(entry.url);photoUrls.delete(key);m.newFiles=m.newFiles.filter(x=>x.key!==key);}else{if(!m.removed.includes(key))m.removed.push(key);m.photos=m.photos.filter(x=>x!==key);}if(m.coverKey===key)m.coverKey=mealPhotoKeys(m)[0]||null;refreshMealStrip();break;}case'view-photo':{const paths=state.modal?.kind==='meal'?mealPhotoKeys(state.modal):state.modal?.photos||[b.dataset.path];photoViewer.open(paths,Math.max(0,paths.indexOf(b.dataset.path)));break;}case'toggle-milestone':run(async()=>{const m=state.data.milestones.find(x=>x.id===b.dataset.id);await save('milestones',{completed_on:m.completed_on?null:today()},m.id);await refresh();render();});break;case'copy-goals':run(async()=>{const previous=addDays(state.period,-span()),rows=state.data.goals.filter(g=>g.start_date<=addDays(previous,span()-1)&&g.end_date>=previous);if(!rows.length)throw Error('No hay objetivos en el periodo anterior.');let count=0;for(const g of rows){if(periodGoals().some(x=>x.title===g.title))continue;await save('goals',{title:g.title,start_date:state.period,end_date:periodEnd(),tracking:g.tracking,weekly_target:g.weekly_target,template:goalKind(g),target_value:goalTarget(g),target_unit:goalUnit(g),frequency:goalFrequency(g),notes:g.notes||'',completion_mode:completionMode(g)});count++;}await refresh();render();toast(count?`${count} objetivos copiados`:'Esos objetivos ya están en este periodo');});break;case'export':{const blob=new Blob([JSON.stringify({exported_at:new Date().toISOString(),...state.data},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download=`diario-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);break;}case'forgot':run(async()=>{const email=document.querySelector('[name=email]').value.trim();if(!email)throw Error('Escribe tu correo y después pulsa «He olvidado mi contraseña».');const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+import.meta.env.BASE_URL});if(error)throw error;toast('Si la cuenta existe, recibirás un enlace para cambiar la contraseña.');});break;}});
document.addEventListener('keydown',ev=>{if(document.querySelector('.photo-viewer[open]'))return;if(!state.modal)return;if(ev.key==='Escape'&&!state.busy){disposeMealDrafts(state.modal);state.modal=null;render();}if(ev.key==='Tab'){const nodes=[...document.querySelectorAll('.dialog button:not(:disabled),.dialog input,.dialog select,.dialog textarea,.dialog a')].filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
window.addEventListener('online',()=>{if(profile()&&!state.modal)render();toast('Conexión recuperada.');});window.addEventListener('offline',()=>{if(profile()&&!state.modal)render();toast('Sin conexión. Necesitas internet para guardar.',true);});
async function loadSession(){state.loading=true;render();try{await Promise.all([refresh(),refreshAdminRole()]);state.error='';if(profile()){state.period=startFor(today());state.reportWeek=mondayOf(today());if(!profile().onboarding_completed){state.tourStep=0;state.view='summary';state.open=today();}}}catch(err){state.error=message(err);}finally{state.loading=false;render();if(state.error&&!profile()){root.innerHTML=`<main class="setup"><h1>No se pudo abrir el diario</h1><p>${e(state.error)}</p>${btn('refresh-session','Reintentar','primary')}</main>`;root.querySelector('button').onclick=loadSession;}}}
async function boot(){if(!db){state.loading=false;render();return;}db.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){state.recovery=true;state.session=session;state.loading=false;renderAuth();}if(event==='SIGNED_OUT'&&!state.demo){resetAdmin();state.view='summary';state.session=null;state.data=Object.fromEntries(tables.map(t=>[t,[]]));state.loading=false;render();}if(event==='TOKEN_REFRESHED')state.session=session;});try{const {data,error}=await db.auth.getSession();if(error)throw error;state.session=data.session;if(state.session&&(incomingInvitation.emailFlow||incomingInvitation.implicitInvite||(state.session.user.invited_at&&!state.session.user.user_metadata?.goingfit_password_set))){state.recovery=true;state.invitePassword=true;}if(state.inviteToken||state.inviteInvalid){state.loading=false;renderInvitation();return;}if(state.recovery){state.loading=false;renderAuth();return;}if(state.session)await loadSession();else{state.loading=false;render();}}catch(err){state.loading=false;render();toast(message(err),true);}}
boot();

function nutritionFields(r){return `<details class="expert-options"><summary>Opciones para expertos</summary><p>Datos del total de esta comida, no por cada 100 g. Deja vacíos los que no conozcas.</p><div class="form-grid">${NUTRIENTS.map(([key,label,unit])=>field(key,label+' ('+unit+')','number',r[key]??'','min="0" step="0.01" inputmode="decimal"')).join('')}</div>${selectField('nutrition_source','Origen de los datos',[['manual','Registro manual'],['label','Etiqueta del alimento'],['app','Otra aplicación'],['estimate','Estimación personal']],r.nutrition_source||'manual')}</details>`;}
function workoutFields(r){return `<details class="expert-options"><summary>Opciones para expertos</summary><p>Valores de esta sesión. Las calorías son una estimación de actividad, sin incluir metabolismo basal.</p><div class="form-grid">${[['kcal_burned','Energía estimada (kcal)'],['distance_km','Distancia (km)'],['steps','Pasos'],['sets','Series iguales'],['reps','Repeticiones por serie'],['load_kg','Carga por repetición (kg)'],['exertion','Esfuerzo percibido (1–10)']].map(([key,label])=>field(key,label,'number',r[key]??'',`min="${['sets','reps','exertion'].includes(key)?1:0}" step="${['steps','sets','reps','exertion'].includes(key)?1:0.01}" ${key==='exertion'?'max="10"':''}`)).join('')}</div>${selectField('calorie_source','Origen del gasto estimado',[['manual','Registro manual'],['watch','Reloj o dispositivo'],['app','Otra aplicación'],['estimate','Estimación personal']],r.calorie_source||'manual')}<fieldset class="muscle-picker"><legend>Grupos musculares, opcional</legend>${Object.entries(MUSCLES).map(([key,label])=>`<label><input type="checkbox" name="muscle_groups" value="${key}" ${r.muscle_groups?.includes(key)?'checked':''}>${label}</label>`).join('')}</fieldset><p class="muted">Para ejercicios de fuerza con distintas cargas o repeticiones, crea un registro por ejercicio o bloque.</p></details>`;}

function mealPhotoKeys(m){return [...(m.photos||[]),...(m.newFiles||[]).map(x=>x.key)];}
function mealPhotoStrip(m){return mealPhotoKeys(m).map((key,i)=>{const draft=m.newFiles.find(x=>x.key===key),cover=m.coverKey===key;return `<div class="meal-photo-choice ${cover?'is-cover':''}"><a href="#" data-action="view-photo" data-path="${e(key)}" aria-label="Abrir fotografía ${i+1}"><img ${draft?`src="${e(draft.url)}"`:`data-photo="${e(key)}"`} alt="Fotografía ${i+1}${cover?' · principal':''}"></a>${btn('remove-photo',icon('close'),'photo-remove',`data-key="${e(key)}" aria-label="Quitar fotografía ${i+1}"`)}${btn('cover-photo',cover?'Principal':'Hacer principal','cover-button',`data-key="${e(key)}" aria-pressed="${cover}" aria-label="${cover?'Foto principal':'Elegir foto principal'}: fotografía ${i+1}"`)}</div>`;}).join('');}
function refreshMealStrip(){const m=state.modal;document.querySelector('.photo-strip').innerHTML=mealPhotoStrip(m);document.querySelector('#new-files').textContent=m.newFiles.length?`${m.newFiles.length} fotos nuevas seleccionadas. Elige la principal y guarda.`:'';hydratePhotos();}
function disposeMealDrafts(m){if(m?.kind!=='meal')return;for(const entry of m.newFiles||[]){URL.revokeObjectURL(entry.url);photoUrls.delete(entry.key);}}

function resetAdmin(){state.isAdmin=false;state.admin={invitations:[],loading:false,error:'',result:null};}
async function refreshAdminRole(){const uid=state.session?.user.id;state.isAdmin=false;if(state.demo||!uid)return;const {data,error}=await db.from('diary_admins').select('user_id').eq('user_id',uid).maybeSingle();if(uid!==state.session?.user.id)return;state.isAdmin=!error&&!!data;if(!state.isAdmin){state.admin={invitations:[],loading:false,error:'',result:null};if(state.view==='admin')state.view='summary';}}
async function loadAdminHistory(showLoading=true){if(!state.isAdmin||state.demo)return;const uid=state.session.user.id;state.admin.error='';if(showLoading){state.admin.loading=true;render();}try{const result=await invokeInvitations(db);if(uid===state.session?.user.id&&state.isAdmin)state.admin.invitations=result.invitations||[];}catch(err){state.admin.error=message(err);}finally{state.admin.loading=false;}}
function renderInvitation(){root.innerHTML=`<main class="setup invitation-welcome"><span class="brand-mark">d.</span><h1>${state.inviteInvalid?'Invitación no válida':'Te han invitado a GoingFit'}</h1><p>${state.inviteInvalid?'Comprueba que has copiado el enlace completo o pide otra invitación.':'Crea tu contraseña y configura tu diario privado.'}</p><div id="auth-error" class="error-banner" role="alert" hidden></div>${state.inviteToken?`${state.session?'<p class="muted">Continuar cambiará a la cuenta invitada en este navegador.</p>':''}${btn('accept-invite','Aceptar invitación','primary wide')}`:''}${btn('invite-login','Volver al acceso','text-button')}</main>`;}
async function acceptInvitation(){const token=state.inviteToken;if(!token||!db)return;const {data,error}=await db.auth.verifyOtp({token_hash:token,type:'invite'});if(error)throw Error('La invitación ha caducado o ya se ha usado. Pide un enlace nuevo.');resetAdmin();photoUrls.clear();state.data=Object.fromEntries(tables.map(t=>[t,[]]));state.session=data.session;state.demo=false;state.inviteToken=null;state.inviteInvalid=false;state.invitePassword=true;state.recovery=true;state.loading=false;state.tourStep=null;state.view='summary';renderAuth();}
